mapper.select:
SELECT c.id AS chunk_id, c.document_id, d.project_id, d.path, d.language, c.chunk_type, c.symbol_name, c.business_summary, c.source_snippet, COALESCE((c.metadata ->> 'startLine')::int, 0) AS start_line, COALESCE((c.metadata ->> 'endLine')::int, 0) AS end_line, (
(CASE WHEN d.path ILIKE '%' || #{kw} || '%' THEN 8 ELSE 0 END + CASE WHEN c.symbol_name ILIKE '%' || #{kw} || '%' THEN 6 ELSE 0 END + CASE WHEN c.source_snippet ILIKE '%' || #{kw} || '%' THEN 1 ELSE 0 END)
) AS score FROM ai_code_chunk c JOIN ai_code_document d ON d.id = c.document_id WHERE c.chunk_type = 'FILE' AND d.project_id IN #{pid} AND (
d.path ILIKE '%' || #{kw} || '%' OR c.symbol_name ILIKE '%' || #{kw} || '%' OR c.source_snippet ILIKE '%' || #{kw} || '%'
) ORDER BY score DESC, d.path ASC, c.id ASC LIMIT #{limit}

SELECT c.id AS chunk_id, c.document_id, d.project_id, d.path, d.language, c.chunk_type, c.symbol_name, c.business_summary, c.source_snippet, COALESCE((c.metadata ->> 'startLine')::int, 0) AS start_line, COALESCE((c.metadata ->> 'endLine')::int, 0) AS end_line, (
(CASE WHEN c.symbol_name ILIKE '%' || #{kw} || '%' THEN 5 ELSE 0 END + CASE WHEN d.path ILIKE '%' || #{kw} || '%' THEN 2 ELSE 0 END + CASE WHEN c.source_snippet ILIKE '%' || #{kw} || '%' THEN 1 ELSE 0 END -- 符号名与检索词完全相同再加一档：getEntity 应压过 getEntityByCode 这类同名前缀， -- 否则一个通用方法名（getEntity）会被几十个派生名挤掉名额 + CASE WHEN lower(c.symbol_name) = lower(#{kw}) THEN 3 ELSE 0 END)
) AS score FROM ai_code_chunk c JOIN ai_code_document d ON d.id = c.document_id WHERE d.project_id IN #{pid} AND c.source_snippet IS NOT NULL AND (
c.symbol_name ILIKE '%' || #{kw} || '%' OR d.path ILIKE '%' || #{kw} || '%' OR c.source_snippet ILIKE '%' || #{kw} || '%'
)
ORDER BY score DESC, length(c.source_snippet) DESC, c.id ASC LIMIT #{limit}

SELECT c.id AS chunk_id, c.document_id, d.project_id, d.path, d.language, c.chunk_type, c.symbol_name, c.business_summary, c.source_snippet, COALESCE((c.metadata ->> 'startLine')::int, 0) AS start_line, COALESCE((c.metadata ->> 'endLine')::int, 0) AS end_line, (
(CASE WHEN lower(c.symbol_name) = lower(#{kw}) THEN 8 ELSE 0 END + CASE WHEN c.symbol_name ILIKE '%' || #{kw} || '%' THEN 5 ELSE 0 END + CASE WHEN c.source_snippet ILIKE '%' || #{kw} || '%' THEN 1 ELSE 0 END)
) AS score FROM ai_code_chunk c JOIN ai_code_document d ON d.id = c.document_id WHERE d.project_id = #{projectId} AND c.chunk_type = 'METHOD' AND c.source_snippet IS NOT NULL AND ( d.path = #{parentClassName} || '.java' OR d.path = #{parentClassName} || '.kt' OR d.path LIKE '%/' || #{parentClassName} || '.java' OR d.path LIKE '%/' || #{parentClassName} || '.kt' ) AND (
c.symbol_name ILIKE '%' || #{kw} || '%' OR c.source_snippet ILIKE '%' || #{kw} || '%'
) ORDER BY score DESC, length(c.source_snippet) DESC, c.id ASC LIMIT #{limit}
